class Solution {
public:
    int maxFreeTime(int eventTime, int k, vector<int>& startTime, vector<int>& endTime) {
        int n = startTime.size();
        auto gap = [&](int i) -> long long {
            if (i == 0) return startTime[0];
            if (i == n) return (long long)eventTime - endTime[n - 1];
            return (long long)startTime[i] - endTime[i - 1];
        };
        long long cur = 0;
        for (int i = 0; i <= k; i++) cur += gap(i);
        long long best = cur;
        for (int i = k + 1; i <= n; i++) {
            cur += gap(i) - gap(i - k - 1);
            if (cur > best) best = cur;
        }
        return (int)best;
    }
};
